

(function () {
  'use strict';

  document.documentElement.classList.add('js');

  var isReducedMotion = false;
  try {
    isReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch (e) {}

  var LEDGER_ENTRIES = [
    { id: 'le-1',  section: 'hero',         side: 'left',  gridRow: 14, date: '02 Nov', desc: 'Salary credit',       amount: 65000, type: 'credit' },
    { id: 'le-2',  section: 'why-ledgio',   side: 'left',  gridRow: 32, date: '03 Nov', desc: 'Fresh groceries',     amount: -1240, type: 'debit'  },
    { id: 'le-3',  section: 'why-ledgio',   side: 'right', gridRow: 36, date: '04 Nov', desc: 'Utilities & WiFi',    amount: -3260, type: 'debit'  },
    { id: 'le-4',  section: 'motion',       side: 'left',  gridRow: 52, date: '05 Nov', desc: 'Coffee & dining',     amount: -1850, type: 'debit'  },
    { id: 'le-5',  section: 'motion',       side: 'right', gridRow: 56, date: '06 Nov', desc: 'Rahul loan repaid',   amount: 2500,  type: 'credit' },
    { id: 'le-6',  section: 'scene-02',     side: 'left',  gridRow: 74, date: '08 Nov', desc: 'Dining cap limit',    amount: 0,     type: 'limit'  },
    { id: 'le-7',  section: 'scene-02',     side: 'right', gridRow: 78, date: '10 Nov', desc: 'Weekly supermarket',  amount: -4150, type: 'debit'  },
    { id: 'le-8',  section: 'scene-03',     side: 'left',  gridRow: 96, date: '12 Nov', desc: 'Emergency reserve',   amount: 5000,  type: 'credit' },
    { id: 'le-9',  section: 'scene-03',     side: 'right', gridRow: 100, date: '14 Nov', desc: 'Peer loan to Priya', amount: -10000, type: 'debit' },
    { id: 'le-10', section: 'scene-04',     side: 'left',  gridRow: 118, date: '16 Nov', desc: 'Freelance bonus',    amount: 15000, type: 'credit' },
    { id: 'le-11', section: 'scene-04',     side: 'right', gridRow: 122, date: '18 Nov', desc: 'Metro transit card', amount: -2400, type: 'debit'  },
    { id: 'le-12', section: 'scene-05',     side: 'left',  gridRow: 140, date: '20 Nov', desc: 'AES-256 vault lock', amount: 0,     type: 'info'   },
    { id: 'le-13', section: 'scene-05',     side: 'right', gridRow: 144, date: '22 Nov', desc: 'Health insurance',   amount: -12600, type: 'debit' },
    { id: 'le-14', section: 'scene-06',     side: 'left',  gridRow: 162, date: '24 Nov', desc: 'Local-first offline', amount: 0,    type: 'info'   },
    { id: 'le-15', section: 'scene-07',     side: 'left',  gridRow: 180, date: '26 Nov', desc: 'Safe surplus alloc', amount: 8000,  type: 'credit' },
    { id: 'le-16', section: 'closing-cta',  side: 'right', gridRow: 198, date: '28 Nov', desc: 'Reconciled ledger',  amount: 0,     type: 'reconciled' }
  ];

  var TOTAL_CREDITS = 95500;
  var TOTAL_DEBITS = 35500;
  var FINAL_BALANCE = 60000;

  var currentBalance = 0;
  var targetBalance = 0;
  var balanceTweenRaf = null;
  var isBalancedLocked = false;
  var cachedSectionOffsets = [];

  function formatCurrency(val) {
    var prefix = val < 0 ? '−₹' : '₹';
    var absVal = Math.abs(Math.round(val));
    return prefix + absVal.toLocaleString('en-IN');
  }

  function initLedgerLayer() {
    var ledgerLayer = document.getElementById('lp-ledger');
    if (!ledgerLayer) return;

    var marginLine = document.createElement('div');
    marginLine.className = 'lp-margin-line';
    ledgerLayer.appendChild(marginLine);

    var entriesFrag = document.createDocumentFragment();
    for (var i = 0; i < LEDGER_ENTRIES.length; i++) {
      var entry = LEDGER_ENTRIES[i];
      var el = document.createElement('div');
      el.id = entry.id;
      el.className = 'lp-entry lp-entry-' + entry.side;
      el.setAttribute('data-section', entry.section);
      el.setAttribute('data-amount', entry.amount);
      el.setAttribute('data-index', i);

      var topPx = entry.gridRow * 32;
      el.style.top = topPx + 'px';

      var amtFormatted = '';
      var amtClass = '';
      if (entry.amount > 0) {
        amtFormatted = '+₹' + entry.amount.toLocaleString('en-IN');
        amtClass = 'amt-pos';
      } else if (entry.amount < 0) {
        amtFormatted = '−₹' + Math.abs(entry.amount).toLocaleString('en-IN');
        amtClass = 'amt-neg';
      } else if (entry.type === 'limit') {
        amtFormatted = '₹5,000 max';
        amtClass = 'amt-neutral';
      } else if (entry.type === 'reconciled') {
        amtFormatted = '✓ 0.00 diff';
        amtClass = 'amt-pos';
      } else {
        amtFormatted = '✓ synced';
        amtClass = 'amt-neutral';
      }

      el.innerHTML = '<span class="lp-entry-dot"></span>' +
                     '<span class="lp-entry-date">' + entry.date + '</span>' +
                     '<span class="lp-entry-desc">' + entry.desc + '</span>' +
                     '<span class="lp-entry-amt ' + amtClass + '">' + amtFormatted + '</span>';

      entriesFrag.appendChild(el);
    }
    ledgerLayer.appendChild(entriesFrag);
  }

  function initRunningBalanceWidget() {
    var widget = document.getElementById('lp-balance-widget');
    if (!widget) return;

    widget.setAttribute('title', 'Decorative running balance of the demo entries\nDebits ₹' + TOTAL_DEBITS.toLocaleString('en-IN') + ' · Credits ₹' + TOTAL_CREDITS.toLocaleString('en-IN') + ' · Net ₹' + FINAL_BALANCE.toLocaleString('en-IN'));
    widget.setAttribute('aria-label', 'Decorative running balance of the demo entries');

    if (!widget.querySelector('.lp-bal-val')) {
      widget.innerHTML =
        '<div class="lp-bal-inner">' +
          '<div class="lp-bal-top">' +
            '<span class="lp-bal-label">LEDGER BALANCE</span>' +
            '<span class="lp-bal-indicator"></span>' +
          '</div>' +
          '<div class="lp-bal-row">' +
            '<span class="lp-bal-val">₹0</span>' +
            '<span class="lp-balanced-stamp" aria-hidden="true">✓ balanced</span>' +
          '</div>' +
          '<div class="lp-bal-tooltip" aria-hidden="true">' +
            '<span>Debits ₹' + TOTAL_DEBITS.toLocaleString('en-IN') + '</span>' +
            '<span>·</span>' +
            '<span>Credits ₹' + TOTAL_CREDITS.toLocaleString('en-IN') + '</span>' +
          '</div>' +
        '</div>';
    }

    if (isReducedMotion) {
      setWidgetFinalState();
    }
  }

  function setWidgetFinalState() {
    var widget = document.getElementById('lp-balance-widget');
    if (!widget) return;
    var valEl = widget.querySelector('.lp-bal-val');
    if (valEl) valEl.textContent = formatCurrency(FINAL_BALANCE);
    widget.classList.add('is-balanced');
    isBalancedLocked = true;
  }

  function tweenBalance(target) {
    if (isReducedMotion || isBalancedLocked) return;
    targetBalance = target;

    if (balanceTweenRaf) cancelAnimationFrame(balanceTweenRaf);

    var startVal = currentBalance;
    var startTime = performance.now();
    var duration = 400; // 400ms duration per requirement

    function step(now) {
      var elapsed = now - startTime;
      var progress = Math.min(1, elapsed / duration);
      var ease = 1 - Math.pow(1 - progress, 3);
      currentBalance = Math.round(startVal + (targetBalance - startVal) * ease);

      var widget = document.getElementById('lp-balance-widget');
      if (widget) {
        var valEl = widget.querySelector('.lp-bal-val');
        if (valEl) valEl.textContent = formatCurrency(currentBalance);
      }

      if (progress < 1) {
        balanceTweenRaf = requestAnimationFrame(step);
      } else {
        currentBalance = targetBalance;
        balanceTweenRaf = null;
      }
    }

    balanceTweenRaf = requestAnimationFrame(step);
  }

  function recalculateRunningBalance() {
    if (isBalancedLocked) return;

    var inkedEntries = document.querySelectorAll('#lp-ledger .lp-entry.is-inked');
    var sum = 0;
    for (var i = 0; i < inkedEntries.length; i++) {
      var amt = parseInt(inkedEntries[i].getAttribute('data-amount'), 10) || 0;
      sum += amt;
    }

    tweenBalance(sum);
  }

  function cacheOffsets() {
    cachedSectionOffsets = [];
    var sections = document.querySelectorAll('section[id], header, footer, #closing-cta');
    for (var i = 0; i < sections.length; i++) {
      var sec = sections[i];
      var rect = sec.getBoundingClientRect();
      cachedSectionOffsets.push({
        id: sec.id || '',
        top: rect.top + window.pageYOffset,
        bottom: rect.bottom + window.pageYOffset,
        height: rect.height,
        el: sec
      });
    }

    var entryEls = document.querySelectorAll('#lp-ledger .lp-entry');
    for (var j = 0; j < entryEls.length; j++) {
      var entryEl = entryEls[j];
      var secId = entryEl.getAttribute('data-section');
      var matchedSec = document.getElementById(secId);
      if (matchedSec) {
        var secTop = matchedSec.getBoundingClientRect().top + window.pageYOffset;
        var offsetRow = parseInt(entryEl.getAttribute('data-index'), 10) % 2 === 0 ? 0 : 2;
        var snappedY = Math.round((secTop + 64 + offsetRow * 32) / 32) * 32;
        entryEl.style.top = snappedY + 'px';
      }
    }
  }

  function inkEntriesForSection(sectionId) {
    var matching = document.querySelectorAll('#lp-ledger .lp-entry[data-section="' + sectionId + '"]:not(.is-inked)');
    if (!matching.length) return;

    for (var i = 0; i < matching.length; i++) {
      (function (el, delay) {
        setTimeout(function () {
          el.classList.add('is-inked');
          recalculateRunningBalance();

          setTimeout(function () {
            el.classList.add('is-settled');
          }, 600);
        }, delay);
      })(matching[i], i * 150);
    }
  }

  function setupScrollAndAppearChoreography() {
    var headings = document.querySelectorAll('[data-appear="heading"]');
    for (var h = 0; h < headings.length; h++) {
      var heading = headings[h];
      if (!heading.querySelector('.appear-line-mask')) {
        var html = heading.innerHTML;
        var parts = html.split(/<br\s*\/?>/i);
        if (parts.length > 1) {
          heading.innerHTML = parts.map(function (p, idx) {
            return '<span class="appear-line-mask"><span class="appear-line-text" style="--line: ' + idx + '">' + p.trim() + '</span></span>';
          }).join('');
        } else {
          heading.innerHTML = '<span class="appear-line-mask"><span class="appear-line-text" style="--line: 0">' + html + '</span></span>';
        }
      }
    }

    var appearEls = document.querySelectorAll('[data-appear]');
    if ('IntersectionObserver' in window && !isReducedMotion) {
      var appearObserver = new IntersectionObserver(function (entries) {
        for (var i = 0; i < entries.length; i++) {
          var entry = entries[i];
          if (entry.isIntersecting) {
            var target = entry.target;
            target.classList.add('is-appeared');

            var parentSec = target.closest('section');
            if (parentSec && parentSec.id) {
              setTimeout(function () {
                inkEntriesForSection(parentSec.id);
              }, 150);
            }

            if (target.getAttribute('data-appear') === 'count') {
              animateCount(target);
            }

            appearObserver.unobserve(target);
          }
        }
      }, {
        threshold: 0.18,
        rootMargin: '0px 0px -40px 0px'
      });

      for (var a = 0; a < appearEls.length; a++) {
        appearObserver.observe(appearEls[a]);
      }

      var closingSec = document.getElementById('closing-cta') || document.querySelector('.section-closing');
      if (closingSec) {
        var closingObserver = new IntersectionObserver(function (entries) {
          for (var c = 0; c < entries.length; c++) {
            if (entries[c].isIntersecting && entries[c].intersectionRatio >= 0.35) {
              setWidgetFinalState();
              var allUninked = document.querySelectorAll('#lp-ledger .lp-entry:not(.is-inked)');
              for (var u = 0; u < allUninked.length; u++) {
                allUninked[u].classList.add('is-inked', 'is-settled');
              }
            }
          }
        }, {
          threshold: [0.35, 0.5]
        });
        closingObserver.observe(closingSec);
      }
    } else {
      for (var f = 0; f < appearEls.length; f++) {
        appearEls[f].classList.add('is-appeared');
      }
      var allEntries = document.querySelectorAll('#lp-ledger .lp-entry');
      for (var e = 0; e < allEntries.length; e++) {
        allEntries[e].classList.add('is-inked', 'is-settled');
      }
      setWidgetFinalState();
    }

    setTimeout(function () {
      var pendingAppears = document.querySelectorAll('[data-appear]:not(.is-appeared)');
      for (var p = 0; p < pendingAppears.length; p++) {
        pendingAppears[p].classList.add('is-appeared');
      }
    }, 3000);
  }

  function animateCount(el) {
    var rawText = el.getAttribute('data-count') || el.textContent.trim();
    var match = rawText.match(/([^\d]*)([\d,]+)(\.?\d*)([^\d]*)/);
    if (!match) return;

    var prefix = match[1] || '';
    var targetNum = parseInt(match[2].replace(/,/g, ''), 10);
    var suffix = match[4] || '';

    var start = 0;
    var duration = 800;
    var startTime = performance.now();

    function update(now) {
      var progress = Math.min(1, (now - startTime) / duration);
      var current = Math.round(start + (targetNum - start) * (1 - Math.pow(1 - progress, 3)));
      el.textContent = prefix + current.toLocaleString('en-IN') + suffix;
      if (progress < 1) requestAnimationFrame(update);
    }
    requestAnimationFrame(update);
  }

  document.addEventListener('visibilitychange', function () {
    if (document.hidden) {
      if (balanceTweenRaf) {
        cancelAnimationFrame(balanceTweenRaf);
        balanceTweenRaf = null;
      }
    }
  });

  var resizeTimer = null;
  window.addEventListener('resize', function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(cacheOffsets, 150);
  }, { passive: true });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  function init() {
    initLedgerLayer();
    initRunningBalanceWidget();
    cacheOffsets();
    setupScrollAndAppearChoreography();

    setTimeout(function () {
      inkEntriesForSection('hero');
    }, 300);
  }

  window.__LEDGIO_LEDGER__ = {
    entries: LEDGER_ENTRIES,
    getCurrentBalance: function () { return currentBalance; },
    getFinalBalance: function () { return FINAL_BALANCE; },
    recalculate: recalculateRunningBalance,
    setFinalState: setWidgetFinalState
  };

})();
